sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.lib-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 12px;
}

.lib-series-link {
  padding: 0 0 10px 0;
}

.lib-card {
  display: block;
  text-decoration: none;
  border: 1px solid rgba(0,0,0,0.12);
  border-radius: 10px;
  overflow: hidden;
  background: #fff;
  position: relative;
}

.lib-card:hover {
  border-color: rgba(0,0,0,0.25);
}

.lib-card-image {
  height: 240px;
  background: rgba(0,0,0,0.04);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.lib-card-image img {
  max-height: 100%;
  max-width: 100%;
  object-fit: cover;
}

.lib-card-image-placeholder {
  width: 60%;
  height: 70%;
  border: 1px dashed rgba(0,0,0,0.25);
  border-radius: 8px;
}

.lib-seq-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  padding: 6px 8px;
  border-radius: 10px;
  background: rgba(255,255,255,0.9);
  border: 1px solid rgba(0,0,0,0.12);
  font-weight: 700;
  font-size: 12px;
  color: rgba(0,0,0,0.85);
}

.lib-card-body {
  padding: 10px 12px 12px;
}

.lib-card-title {
  font-weight: 600;
  color: #1a1a1a;
  line-height: 1.2;
}

.lib-card-subtitle {
  margin-top: 6px;
  font-size: 12px;
  color: rgba(0,0,0,0.65);
}

.lib-meta-link {
  text-decoration: none;
}

.lib-meta-link:hover {
  text-decoration: underline;
}

.lib-empty, .lib-error {
  padding: 12px;
}

sp_widget.script:
(function () {
  data.error = "";
  data.items = [];
  data.series = { sys_id: "", display: "" };

  var opts = options || {};

  var mode = (opts.mode || "series").trim(); // "series" or "book"

  var bookTable = (opts.book_table || "").trim();
  var m2mTable = (opts.m2m_table || "").trim();

  var m2mSeriesField = (opts.m2m_series_field || "series").trim();
  var m2mBookField = (opts.m2m_book_field || "book").trim();
  var m2mSeqField = (opts.m2m_sequence_field || "sequence_number").trim();

  var sysIdParam = (opts.sys_id_param || "sys_id").trim();
  var urlSysId = ("" + ($sp.getParameter(sysIdParam) || "")).trim();

  var bookSeriesField = (opts.book_series_field || "series").trim();

  var titleField = (opts.title_field || "title").trim();
  var subtitleField = (opts.subtitle_field || "").trim();
  var imageField = (opts.image_field || "").trim();

  var limit = parseInt(opts.limit, 10);
  if (isNaN(limit) || limit <= 0) limit = 50;
  if (limit > 200) limit = 200;

  data.ui = {
    link_page: (opts.link_page || "library_book").trim(),
    link_param: (opts.link_param || "sys_id").trim(),
    series_link_page: (opts.series_link_page || "library_series").trim(),
    show_series_link: (opts.show_series_link === true || opts.show_series_link === "true"),
    show_sequence_badge: (opts.show_sequence_badge === true || opts.show_sequence_badge === "true"),
    empty_text: (opts.empty_text || "No records found.").trim()
  };

  if (!urlSysId) {
    data.error = "Missing sys_id in URL";
    return;
  }
  if (!m2mTable || !bookTable) {
    data.error = "Missing option: m2m_table or book_table";
    return;
  }

  // Resolve series sys_id
  var seriesSysId = "";
  if (mode === "series") {
    seriesSysId = urlSysId;
  } else if (mode === "book") {
    // URL sys_id is a book sys_id -> fetch its series reference
    var b = new GlideRecord(bookTable);
    if (!b.isValid()) {
      data.error = "Invalid book table: " + bookTable;
      return;
    }
    if (!b.get(urlSysId)) {
      data.error = "Book not found";
      return;
    }
    if (!b.isValidField(bookSeriesField)) {
      data.error = "Invalid book_series_field: " + bookSeriesField;
      return;
    }
    seriesSysId = ("" + b.getValue(bookSeriesField)).trim();
    data.series.sys_id = seriesSysId;
    data.series.display = b.getDisplayValue(bookSeriesField) || "";
    if (!seriesSysId) {
      // Book has no series -> empty state, not an error
      return;
    }
  } else {
    data.error = "Invalid mode: " + mode;
    return;
  }

  // Query M2M rows for this series
  var m2m = new GlideRecord(m2mTable);
  if (!m2m.isValid()) {
    data.error = "Invalid M2M table: " + m2mTable;
    return;
  }
  if (!m2m.isValidField(m2mSeriesField) || !m2m.isValidField(m2mBookField)) {
    data.error = "Invalid M2M field config";
    return;
  }

  m2m.addQuery(m2mSeriesField, seriesSysId);
  if (m2mSeqField && m2m.isValidField(m2mSeqField)) m2m.orderBy(m2mSeqField);
  else m2m.orderBy("sys_created_on");
  m2m.setLimit(limit);
  m2m.query();

  var order = [];
  var bookIds = [];
  var seqByBook = {};

  while (m2m.next()) {
    var bId = ("" + m2m.getValue(m2mBookField)).trim();
    if (!bId) continue;

    var seq = "";
    if (m2mSeqField && m2m.isValidField(m2mSeqField)) seq = ("" + m2m.getValue(m2mSeqField)).trim();

    if (!seqByBook[bId]) {
      seqByBook[bId] = seq;
      bookIds.push(bId);
      order.push({ bookSysId: bId });
    }
  }

  if (bookIds.length === 0) return;

  var book = new GlideRecord(bookTable);
  if (!book.isValid()) {
    data.error = "Invalid book table: " + bookTable;
    return;
  }

  book.addQuery("sys_id", "IN", bookIds.join(","));
  book.query();

  var bookMap = {};
  while (book.next()) {
    var id = book.getUniqueValue();
    var item = {
      sys_id: id,
      title: "",
      subtitle: "",
      image_url: "",
      sequence: seqByBook[id] || ""
    };

    if (titleField && book.isValidField(titleField)) item.title = book.getDisplayValue(titleField) || "";
    else item.title = book.getDisplayValue() || "";

    if (subtitleField) {
      try { item.subtitle = book.getDisplayValue(subtitleField) || ""; } catch (e) { item.subtitle = ""; }
    }

    if (imageField && book.isValidField(imageField)) item.image_url = book.getDisplayValue(imageField) || "";

    bookMap[id] = item;
  }

  for (var i = 0; i < order.length; i++) {
    var key = order[i].bookSysId;
    if (bookMap[key]) data.items.push(bookMap[key]);
  }

  // Series display (if we're in series mode, we can still set it via a quick lookup)
  if (mode === "series") {
    data.series.sys_id = seriesSysId;
  }
})();
